import {CATEGORIES,metadata,setMetadata,createGroup,submitGroup,reviewSubmission,submissionCurrent,proposeBatch,handoff} from './workflow.js';
export function installWorkflow({getProject,selected,actor,mutate,download,toast}){
 const panel=document.createElement('section');panel.className='workflow-panel';
 panel.innerHTML=`<h2>Label & hand off</h2><p>Describe the motion and where it belongs. Select frames to collect into an animation.</p><label>Category <select id="category">${CATEGORIES.map(v=>`<option>${v}</option>`).join('')}</select></label><label>Tags <input id="frame-tags" placeholder="horizontal, airborne, left" maxlength="800"></label><div id="tag-presets"></div><label>Description <textarea id="frame-description" maxlength="2000" placeholder="Pose, intent, contact points and use in the dashboard"></textarea></label><button id="save-labels">Save labels to selected frames</button><label>Find frames <input id="frame-search" placeholder="Name, category, tag or description"></label><div class="batch-actions"><button id="select-current">Current frame</button><button id="select-all">All frames</button><button id="select-none">Clear selection</button></div><div id="batch-frames"></div><label>Animation name <input id="group-name" maxlength="120" placeholder="Jump across — horizontal flight"></label><button id="create-group">Save selected as animation</button><label>Saved animations <select id="group-select"></select></label><button id="select-group">Select animation frames</button><label>Handoff / review notes <textarea id="handoff-notes" maxlength="2000" placeholder="What changed, what to refine, where Codex should use it"></textarea></label><button id="submit-group" class="primary">Submit animation for review</button><button id="export-handoff">Download Codex handoff</button><p class="hint">Submission saves an exact version here. Download and attach the handoff to Codex; it is not sent automatically.</p><div id="submissions"></div>`;
 document.querySelector('.inspector').append(panel);const $=s=>panel.querySelector(s);let chosen=new Set(),selectedId,selectedMetadata,groupId='';
 const editGroup=document.createElement('button');editGroup.textContent='Update animation labels & selection';editGroup.id='update-group';$('#select-group').after(editGroup);
 const previewLabel=document.createElement('label'),previewGroup=document.createElement('input');previewGroup.type='checkbox';previewGroup.checked=true;previewGroup.id='preview-group';previewLabel.append(previewGroup,document.createTextNode('Playback saved animation only'));editGroup.after(previewLabel);
 const safe=fn=>{try{fn();}catch(e){toast(e.message);}};
 const tags=()=>$('#frame-tags').value.split(',').map(s=>s.trim()).filter(Boolean);
 const values=()=>metadata({category:$('#category').value,tags:tags(),description:$('#frame-description').value});
 const ids=()=>getProject().frames.filter(f=>chosen.has(f.id)).map(f=>f.id);
 for(const tag of ['horizontal','airborne','takeoff','landing','loop','left','right','bed','bowl','card-edge']){const b=document.createElement('button');b.textContent=tag;b.onclick=()=>{const list=tags();if(!list.includes(tag))list.push(tag);$('#frame-tags').value=list.join(', ');};$('#tag-presets').append(b);}
 $('#save-labels').onclick=()=>safe(()=>{mutate(()=>setMetadata(getProject(),ids(),values(),actor()));toast('Labels saved; pixel authorship retained.');});
 $('#select-current').onclick=()=>{chosen=new Set([selected().id]);render();};$('#select-all').onclick=()=>{chosen=new Set(getProject().frames.map(f=>f.id));render();};$('#select-none').onclick=()=>{chosen.clear();render();};$('#frame-search').oninput=()=>render();
 $('#create-group').onclick=()=>safe(()=>{mutate(()=>{const g=createGroup(getProject(),{name:$('#group-name').value,frameIds:ids(),...values()},actor());groupId=g.id;});toast('Animation saved.');});
 $('#group-select').onchange=()=>{groupId=$('#group-select').value;render();};
 $('#select-group').onclick=()=>{const g=getProject().groups?.find(g=>g.id===groupId);if(g){chosen=new Set(g.frameIds);$('#group-name').value=g.name;$('#category').value=g.category;$('#frame-tags').value=g.tags.join(', ');$('#frame-description').value=g.description;render();}};
 editGroup.onclick=()=>safe(()=>{mutate(()=>{const g=getProject().groups?.find(g=>g.id===groupId);if(!g)throw Error('Choose an animation group.');const frameIds=ids(),name=$('#group-name').value.trim();if(!frameIds.length||!name||name.length>120)throw Error('Supply a name and selected frames.');Object.assign(g,{name,frameIds,...values()});});toast('Animation updated; previous submissions retain their exact version.');});
 $('#submit-group').onclick=()=>safe(()=>{mutate(()=>submitGroup(getProject(),groupId,$('#handoff-notes').value,actor()));toast('Exact animation version submitted for human review.');});
 $('#export-handoff').onclick=()=>safe(()=>download('cat-codex-handoff.json',JSON.stringify(handoff(getProject(),groupId),null,2)));
 function render(){const p=getProject();if(!p)return;const f=selected(),signature=JSON.stringify(f.metadata||{});if(selectedId!==f.id||selectedMetadata!==signature){if(!selectedId)chosen.add(f.id);selectedId=f.id;selectedMetadata=signature;const m=f.metadata||{};$('#category').value=m.category||'other';$('#frame-tags').value=(m.tags||[]).join(', ');$('#frame-description').value=m.description||'';}
  const search=$('#frame-search').value.toLowerCase();$('#batch-frames').replaceChildren();p.frames.forEach((frame,i)=>{if(![frame.name,frame.metadata?.category,...(frame.metadata?.tags||[]),frame.metadata?.description].join(' ').toLowerCase().includes(search))return;const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=chosen.has(frame.id);check.onchange=()=>{if(check.checked)chosen.add(frame.id);else chosen.delete(frame.id);};label.append(check,document.createTextNode(`${i+1}. ${frame.name} · ${frame.origin}`));$('#batch-frames').append(label);});
  const groups=p.groups||[];if(!groups.some(g=>g.id===groupId))groupId=groups[0]?.id||'';$('#group-select').replaceChildren();for(const g of groups){const opt=document.createElement('option');opt.value=g.id;opt.textContent=`${g.name} · ${g.frameIds.length} frames · ${g.category}`;$('#group-select').append(opt);}$('#group-select').value=groupId;
  $('#submissions').replaceChildren();for(const s of [...(p.submissions||[])].reverse()){const box=document.createElement('div'),text=document.createElement('p'),current=submissionCurrent(p,s);text.textContent=`${s.snapshot.group.name} · ${s.status}${current?'':' · changed since submission'} · ${s.notes}`;box.append(text);for(const [status,label] of [['confirmed','Confirm exact batch'],['changes-requested','Request changes'],['rejected','Reject']]){const b=document.createElement('button');b.textContent=label;b.disabled=!current||actor()!=='human';b.onclick=()=>safe(()=>mutate(()=>reviewSubmission(p,s.id,status,$('#handoff-notes').value,actor())));box.append(b);}$('#submissions').append(box);}
 }
 const tools=[{name:'propose_ai_animation',description:'Atomically propose an animation of AI candidate frames with labels and a description. Requires human review; never submits, confirms or installs.',inputSchema:{type:'object',properties:{name:{type:'string'},category:{type:'string',enum:CATEGORIES},description:{type:'string'},tags:{type:'array',items:{type:'string'}},frames:{type:'array',minItems:1,maxItems:96,items:{type:'object',properties:{name:{type:'string'},rows:{type:'array',items:{type:'string'},minItems:24,maxItems:24},durationMs:{type:'number'},parentId:{type:'string'},metadata:{type:'object'}},required:['rows'],additionalProperties:false}}},required:['name','frames'],additionalProperties:false},execute:input=>{let g;mutate(()=>{g=proposeBatch(getProject(),input);groupId=g.id;chosen=new Set(g.frameIds);});return {content:[{type:'text',text:JSON.stringify(g)}]};}}];
 tools.push({name:'get_animation_handoff',description:'Read animation labels, descriptions and exact review snapshots. current=false means a submission changed and must be resubmitted.',inputSchema:{type:'object',properties:{groupId:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>({content:[{type:'text',text:JSON.stringify(handoff(getProject(),input.groupId))}]})});
 tools.push({name:'label_ai_frames',description:'Set category, tags and description on existing frames as an AI metadata operation. Does not change pixel authorship or confirm artwork.',inputSchema:{type:'object',properties:{frameIds:{type:'array',minItems:1,maxItems:96,items:{type:'string'}},category:{type:'string',enum:CATEGORIES},tags:{type:'array',maxItems:20,items:{type:'string'}},description:{type:'string'}},required:['frameIds'],additionalProperties:false},execute:input=>{mutate(()=>setMetadata(getProject(),input.frameIds,input,'ai'));selectedId=null;render();return {content:[{type:'text',text:JSON.stringify({frameIds:input.frameIds,actor:'ai'})}]};}});
 return {render,tools,playbackFrames:()=>{const p=getProject(),g=previewGroup.checked&&p.groups?.find(g=>g.id===groupId),frames=g?.frameIds.map(fid=>p.frames.find(f=>f.id===fid)).filter(Boolean);return frames?.length?frames:p.frames;}};
}
